corrected_code:
const express = require('express');
const router = express.Router();
const { Client } = require('@elastic/elasticsearch');
const esClient = new Client({ node: process.env.ELASTICSEARCH_URL });

router.get('/api/v1/health-records/:recordId', verifyPatientSession, async (req, res) => {
  const { recordId } = req.params;

  try {
    const response = await esClient.get({
      index: 'patient_health_encounters',
      id: recordId
    });
    if (response._source.patient_id !== req.user.patientId) {
      return res.status(403).json({ message: 'Forbidden: access denied to medical encounter' });
    }
    return res.json(response._source);
  } catch (err) {
    if (err.meta?.statusCode === 404) {
      return res.status(404).json({ message: 'Record not found' });
    }
    return res.status(500).json({ message: 'Search engine error' });
  }
});
